{"file_path":"src/cli.js","content":"import { readFileSync } from 'node:fs'

class ParseError extends Error {}
const fail = (m) => { throw new ParseError(m) }

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'json' && mode !== 'keys') {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}

const isWs = (c) => c === ' ' || c === '\t'
const isBare = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)
const isComment = (c) => c === '#' || c === ';'

const newTable = () => ({ t: 'table', map: new Map(), header: false })

class Line {
  constructor(s) { this.s = s; this.i = 0 }
  get c() { return this.s[this.i] }
  ws() { while (isWs(this.c)) this.i++ }
  // at end of meaningful content (end or comment)
  atEnd() { return this.i >= this.s.length || isComment(this.c) }
}

function parseBasic(L) {
  L.i++
  let out = ''
  for (;;) {
    if (L.i >= L.s.length) fail('unterminated string')
    const c = L.c
    if (c === '"') { L.i++; return out }
    if (c === '\\') {
      L.i++
      if (L.i >= L.s.length) fail('unterminated string')
      const e = L.c
      L.i++
      if (e === '"') out += '"'
      else if (e === '\\') out += '\\'
      else if (e === 'n') out += '\n'
      else if (e === 't') out += '\t'
      else if (e === 'r') out += '\r'
      else if (e === '0') out += '\0'
      else if (e === 'u') {
        const h = L.s.slice(L.i, L.i + 4)
        if (!/^[0-9a-fA-F]{4}$/.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        L.i += 4
      } else fail('invalid escape \\' + String.fromCodePoint(e.codePointAt(0)))
    } else { out += c; L.i++ }
  }
}

function parseLiteral(L) {
  const j = L.s.indexOf("'", L.i + 1)
  if (j < 0) fail('unterminated string')
  const r = L.s.slice(L.i + 1, j)
  L.i = j + 1
  return r
}

function parseName(L) {
  const c = L.c
  if (c === '"') return parseBasic(L)
  if (c === "'") return parseLiteral(L)
  if (!isBare(c)) fail('expected a name')
  const st = L.i
  while (isBare(L.c)) L.i++
  return L.s.slice(st, L.i)
}

function parseDotted(L) {
  const names = [parseName(L)]
  for (;;) {
    const save = L.i
    L.ws()
    if (L.c === '.') {
      L.i++
      L.ws()
      names.push(parseName(L))
    } else { L.i = save; return names }
  }
}

const INT = /^[+-]?\d+(_\d+)*$/
const FLOAT = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

function parseValue(L, path) {
  if (L.atEnd() || L.c === ',' || L.c === ']' || L.c === '}') fail('expected a value')
  const c = L.c
  if (c === '"') return { t: 'string', v: parseBasic(L) }
  if (c === "'") return { t: 'string', v: parseLiteral(L) }
  if (c === '[') {
    L.i++
    const items = []
    L.ws()
    if (L.c === ']') { L.i++; return { t: 'array', items, aot: false } }
    for (;;) {
      L.ws()
      items.push(parseValue(L, path + '[' + items.length + ']'))
      L.ws()
      if (L.c === ',') {
        L.i++
        L.ws()
        if (L.c === ']') { L.i++; break }
      } else if (L.c === ']') { L.i++; break }
      else fail('unterminated array')
    }
    return { t: 'array', items, aot: false }
  }
  if (c === '{') {
    L.i++
    const tbl = newTable()
    L.ws()
    if (L.c === '}') { L.i++; return tbl }
    for (;;) {
      L.ws()
      const names = parseDotted(L)
      L.ws()
      if (L.c !== '=') fail('expected = in an inline table')
      L.i++
      L.ws()
      const v = parseValue(L, path + '.' + names.join('.'))
      assign(tbl, path, names, v)
      L.ws()
      if (L.c === ',') { L.i++; continue }
      if (L.c === '}') { L.i++; break }
      fail('unterminated inline table')
    }
    return tbl
  }
  const st = L.i
  while (L.i < L.s.length && !isWs(L.c) && L.c !== ',' && L.c !== ']' && L.c !== '}') L.i++
  const w = L.s.slice(st, L.i)
  if (w === 'true' || w === 'false') return { t: 'boolean', v: w === 'true' }
  if (INT.test(w)) return { t: 'integer', v: BigInt(w.replace(/_/g, '')) }
  if (FLOAT.test(w)) return { t: 'float', v: Number(w.replace(/_/g, '')) }
  return fail('invalid value ' + w)
}

const join = (p, k) => (p === '' ? k : p + '.' + k)

// Descend into child `name` of table, creating a table if absent; arrays of tables use last element.
function descend(tbl, name, path) {
  let n = tbl.map.get(name)
  if (n === undefined) { n = newTable(); tbl.map.set(name, n) }
  if (n.t === 'table') return n
  if (n.t === 'array' && n.aot) return n.items[n.items.length - 1]
  return fail(path + ' is not a table')
}

function assign(tbl, prefix, names, value) {
  let p = prefix
  for (let k = 0; k < names.length - 1; k++) {
    p = join(p, names[k])
    tbl = descend(tbl, names[k], p)
  }
  const last = names[names.length - 1]
  p = join(p, last)
  if (tbl.map.has(last)) fail('key ' + p + ' is defined twice')
  tbl.map.set(last, value)
}

function parseHeader(L, root) {
  L.i++
  const aot = L.c === '['
  if (aot) L.i++
  L.ws()
  const names = parseDotted(L)
  L.ws()
  if (L.c !== ']') fail('unterminated table header')
  L.i++
  if (aot) {
    if (L.c !== ']') fail('unterminated table header')
    L.i++
  }
  L.ws()
  if (!L.atEnd()) fail('trailing text after a table header')
  let tbl = root
  let p = ''
  for (let k = 0; k < names.length - 1; k++) {
    p = join(p, names[k])
    tbl = descend(tbl, names[k], p)
  }
  const last = names[names.length - 1]
  p = join(p, last)
  const n = tbl.map.get(last)
  if (aot) {
    if (n === undefined) {
      const fresh = newTable()
      tbl.map.set(last, { t: 'array', items: [fresh], aot: true })
      return fresh
    }
    if (n.t !== 'array' || !n.aot) fail(p + ' is not an array of tables')
    const fresh = newTable()
    n.items.push(fresh)
    return fresh
  }
  if (n === undefined) {
    const fresh = newTable()
    fresh.header = true
    tbl.map.set(last, fresh)
    return fresh
  }
  if (n.t !== 'table') fail(p + ' is not a table')
  if (n.header) fail('table ' + p + ' is defined twice')
  n.header = true
  return n
}

const cmp = (a, b) => {
  const x = Array.from(a, (ch) => ch.codePointAt(0))
  const y = Array.from(b, (ch) => ch.codePointAt(0))
  for (let i = 0; i < Math.min(x.length, y.length); i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}

function toJson(n, ind) {
  const pad = '  '.repeat(ind + 1)
  const end = '  '.repeat(ind)
  switch (n.t) {
    case 'table': {
      const ks = [...n.map.keys()].sort(cmp)
      if (!ks.length) return '{}'
      return '{\n' + ks.map((k) => pad + JSON.stringify(k) + ': ' + toJson(n.map.get(k), ind + 1)).join(',\n') + '\n' + end + '}'
    }
    case 'array':
      if (!n.items.length) return '[]'
      return '[\n' + n.items.map((v) => pad + toJson(v, ind + 1)).join(',\n') + '\n' + end + ']'
    case 'integer': return n.v.toString()
    case 'float': return JSON.stringify(n.v)
    default: return JSON.stringify(n.v)
  }
}

function toKeys(n, path, out) {
  if (n.t === 'table') {
    for (const k of [...n.map.keys()].sort(cmp)) {
      const c = n.map.get(k)
      const p = join(path, k)
      out.push(p + ' ' + c.t)
      toKeys(c, p, out)
    }
  } else if (n.t === 'array') {
    n.items.forEach((c, i) => {
      const p = path + '[' + i + ']'
      out.push(p + ' ' + c.t)
      toKeys(c, p, out)
    })
  }
}

const input = readFileSync(0, 'utf8')
const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const root = newTable()
let cur = root
let curPath = ''
try {
  for (let ln = 0; ln < lines.length; ln++) {
    try {
      const L = new Line(lines[ln])
      L.ws()
      if (L.i >= L.s.length || isComment(L.c)) continue
      if (L.c === '[') {
        cur = parseHeader(L, root)
        continue
      }
      const names = parseDotted(L)
      L.ws()
      if (L.c !== '=') fail('expected key = value')
      L.i++
      L.ws()
      const v = parseValue(L, join(curPath, names.join('.')))
      L.ws()
      if (!L.atEnd()) fail('trailing text after a value')
      assign(cur, curPath, names, v)
    } catch (e) {
      if (e instanceof ParseError) throw new ParseError('error: line ' + (ln + 1) + ': ' + e.message)
      throw e
    }
  }
} catch (e) {
  if (!(e instanceof ParseError)) throw e
  process.stderr.write(e.message + '\n')
  process.exit(2)
}

if (mode === 'json') process.stdout.write(toJson(root, 0) + '\n')
else {
  const out = []
  toKeys(root, '', out)
  process.stdout.write(out.map((l) => l + '\n').join(''))
}
"}

